import re
from pwn import *
from Crypto.Util.number import bytes_to_long, long_to_bytes
from collections import Counter

# Deck info: 4 suits x 16 values = 64 cards
card_value_dict = {0: "Zero", 1: "One", 2: "Two", 3: "Three", 4: "Four", 5: "Five", 6: "Six", 7: "Seven", 8: "Eight", 9: "Nine", 10: "Ten", 11: "Jack", 12: "Queen", 13: "King", 14: "Ace", 15: "Joker"}
suits = ["Spades", "Hearts", "Diamonds", "Clubs"]
# Build card string list
deck = [f"{card_value_dict[v]} of {s}" for s in suits for v in range(16)]

def parse_primes(data):
    m = re.search(r"(\d+), (\d+)", data)
    return int(m.group(1)), int(m.group(2))

def parse_enc_deck(data):
    # deck = [int(x) for x in re.findall(r"\d+", data)]
    # The deck has large integers, let's split correctly
    body = data.split("[",1)[1].rsplit("]",1)[0]
    nums = [int(x.strip().rstrip(",")) for x in body.split() if x.strip().rstrip(",").isdigit()]
    if len(nums)<64:
        # fallback: Some newlines maybe
        nums = []
        for m in re.finditer(r"(\d{40,})", data):
            nums.append(int(m.group(1)))
    return nums

def hand_score(cards):
    # ranks=[0-15], suits (string)
    ranks = sorted([c[1] for c in cards], reverse=True)
    suits = [c[2] for c in cards]
    # is_flush/all same suit
    flush = len(set(suits))==1
    straight = len(set(ranks))==5 and (ranks[0]-ranks[4]==4)
    counts = Counter(ranks)
    q = sorted(counts.values(),reverse=True)
    # Assign hand rank: tuple bigger=better: (rank, highest_rank)
    # Royal Flush, Straight Flush
    if flush:
        if ranks == [15,14,13,12,11]:
            return (9, ranks)
        if straight:
            return (8, ranks)
    if q == [4,1]:
        return (7, ranks)
    if q == [3,2]:
        return (6, ranks)
    if flush:
        return (5, ranks)
    if straight:
        return (4, ranks)
    if q == [3,1,1]:
        return (3, ranks)
    if q == [2,2,1]:
        return (2, ranks)
    if q == [2,1,1,1]:
        return (1, ranks)
    return (0, ranks)

def best_5hand_idxs(cardset):
    # Return indices for best 5-card hand
    from itertools import combinations
    best = (-1,[])
    idxs = range(len(cardset))
    for comb in combinations(idxs,5):
        crt = [cardset[i] for i in comb]
        sc = hand_score(crt)
        if sc>best:
            best = (sc,comb)
    return best[1]


def solve_one_round(r, p, q):
    phi = (p-1)*(q-1)
    N = p*q
    # Choose e,d
    e = 3
    d = pow(e, -1, phi)
    r.sendlineafter('exponent?',str(e))
    r.sendlineafter('exponent as well',str(d))
    ## Wait for enc_deck prompt
    while True:
        data = r.recvuntil(b'Shuffle the deck', drop=False, timeout=10).decode(errors='ignore')
        if 'encrypted deck' in data:
            break
    enc_deck_line = ''
    for line in data.splitlines():
        if 'encrypted deck' in line:
            enc_deck_line = line 
    enc_deck = parse_enc_deck(enc_deck_line)
    ## Find current server_e, from pow(pow(card,server_e,N),e,N) perms
    # Try all possible (for small server_e? But we only have enc_deck, not server_e itself)
    # Instead, for every deck card, precompute the encoding values, since we control e
    # For each possible card string:
    strlongs = [bytes_to_long(card.encode()) for card in deck]
    card_encs = {}
    for i,cardval in enumerate(deck):
        m = strlongs[i]
        enc1 = pow(m, e, N)
        # For all small exponents, or just use enc1 as first layer
        # We don't know server_e, but the server encodes pow(m,server_e,N) then pow(x,player_e,N)
        for se in range(650000, 999999):
            try:
                enc2 = pow(m, se, N)
                test = pow(enc2, e, N)
                if test in enc_deck:
                    card_encs[test]= (cardval, i, m, se)
            except:
                continue
    # Fallback for efficiency: try recovering from enc_deck directly
    # But the space is huge: best to try reverse of pow(m,player_e,N) part? Not feasible.
    # Instead, enumerate for player_e=e=3, only one pow layer needed, server_e is what must be brute-forced (6 digits)
    # But that's too large for this runtime. Instead, let's try the following:
    # Try all deck elements m, for each see which test in enc_deck matches. If it's unique, we found the map.
    matchmap = {}
    for mi,cardstr in enumerate(deck):
        m = bytes_to_long(cardstr.encode())
        vals = [pow(m,e,N)] # Only one pow, can't do both
        # Try to recover mapping (only if unique)
        for test in enc_deck:
            # Try cuberoot under mod N?
            # Not feasible. Instead, hope that for 64 cards, they're all distinct. If so, pick the mapping in order
            matchmap[test] = (cardstr, mi, m)
    # If enc_deck entries not unique, use input order
    enc2str = {}
    for enc_i, enc_val in enumerate(enc_deck):
        enc2str[enc_val] = deck[enc_i] if enc_i<len(deck) else 'UNKNOWN'
    # Now, determine optimal order: first 5 are server hand, next 5 are ours
    # Find strongest possible hand for us, weakest for server
    deck_tuples = []
    for i,card in enumerate(deck):
        suit = card.split(' of ')[1]
        rank = [k for k,v in card_value_dict.items() if v==card.split(' ')[0]][0]
        deck_tuples.append((card, rank, suit, i))
    strongest_idxs = best_5hand_idxs(deck_tuples)
    weakest_idxs = min([comb for comb in combinations(range(64),5)], key=lambda x:hand_score([deck_tuples[i] for i in x]))
    # Put weakest for server (first 5), strongest for us (next 5)
    final_idx_order = list(weakest_idxs)+list(strongest_idxs)
    remainder = [i for i in range(64) if i not in final_idx_order]
    full_order = final_idx_order+remainder
    enc_deck_ordered = [enc_deck[i] for i in full_order]
    # Submit the ordering
    for encval in enc_deck_ordered:
        r.sendlineafter('>>', str(encval))
    cards_used = [deck[i] for i in full_order[:10]]
    return cards_used

def main():
    r = remote('crypto.chal.csaw.io', 5000)
    data = r.recvuntil(b')',timeout=5).decode()
    primes = parse_primes(data)
    wins = 0
    while True:
        cards_used = solve_one_round(r, *primes)
        win_output = r.recvuntil(b'!', timeout=5).decode(errors='ignore')
        print(win_output)
