            wins+=1
        if 'flag' in win_output or 'Congratulations' in win_output:
            try:
                rest = r.recv(timeout=5).decode()
            except:
                rest = ''
            print(rest)
            break
        if wins>=10: break
    r.close()

if __name__ == '__main__':
    main()

