		return 6, hand, "Full House"
	elif is_flush:
		return 5, hand, "Flush"
	elif is_straight:
		return 4, hand, "Straight"
	elif is_three_kind:
		return 3, hand, "Three of a kind"
	elif sum(pair_array)==2:
		return 2, hand, "Two pair"
